// tests/test_cpp_parity.cpp
//
// P0-2: C++ vs NumPy reference parity test at 1e-5 tolerance.
// 
// Loads a weight file and expected outputs generated by
// scripts/reference_mamba3.py --generate, runs C++ inference,
// and compares outputs element-wise.

#include <gtest/gtest.h>
#include "core/ssm_block.h"
#include "core/ssm_inference_core.h"
#include "core/weight_loader.h"
#include <cstring>
#include <cmath>
#include <cstdio>
#include <vector>
#include <memory>

using namespace mamba;

// Test helper: load SSMWeights from file into a single-layer SSMBlock
static std::unique_ptr<SSMBlock> load_parity_block(const char* weight_path) {
    WeightLoader loader;
    int rc = loader.load(weight_path);
    if (rc != 0) {
        fprintf(stderr, "Failed to load weights: %s (rc=%d)\n", weight_path, rc);
        return nullptr;
    }

    const auto& hdr = loader.header();

    auto block = std::make_unique<SSMBlock>(
        hdr.d_state, hdr.d_model, hdr.d_inner,
        hdr.nheads, hdr.headdim, MAX_MIMO_RANK,
        MAX_NUM_BC_HEADS, hdr.cond_dim);

    SSMWeights w{};
    if (loader.dequantize_layer_to(0, w) != 0) {
        fprintf(stderr, "Failed to materialize layer 0 weights\n");
        return nullptr;
    }

    block->set_weights(w);
    loader.unload();

    // Set conditioning (matching Python: cond[0]=0.5, cond[1]=-0.25)
    float cond[COND_DIM] = {0.0f};
    cond[0] = 0.5f;
    cond[1] = -0.25f;
    block->set_conditioning(cond);

    return block;
}

TEST(CppParity, OutputMatchesPythonReference) {
    const char* weight_path = MAMBA_SOURCE_DIR "/build/parity_test_weights.bin";
    const char* expect_path = MAMBA_SOURCE_DIR "/build/parity_expected.bin";

    // Check files exist
    FILE* check = fopen(weight_path, "rb");
    if (!check) {
        GTEST_SKIP() << "Test vectors not generated. Run: "
                      << "python3 scripts/reference_mamba3.py --generate";
    }
    fclose(check);

    check = fopen(expect_path, "rb");
    if (!check) {
        GTEST_SKIP() << "Expected output not generated.";
    }
    fclose(check);

    // Read expected outputs
    std::vector<float> expected;
    {
        FILE* f = fopen(expect_path, "rb");
        fseek(f, 0, SEEK_END);
        long sz = ftell(f);
        fseek(f, 0, SEEK_SET);
        expected.resize(sz / sizeof(float));
        fread(expected.data(), sizeof(float), expected.size(), f);
        fclose(f);
    }

    size_t d_model = 16;  // from --model-dim 16
    size_t num_samples = expected.size() / d_model;
    ASSERT_EQ(expected.size() % d_model, 0u);
    ASSERT_GE(num_samples, 1u);

    // Load C++ block
    auto block = load_parity_block(weight_path);
    ASSERT_NE(block, nullptr);

    // Test inputs matching Python: [0.0, 1.0, -1.0, 0.5, -0.5, ...]
    const float test_inputs[] = {0.0f, 1.0f, -1.0f, 0.5f, -0.5f, 0.25f,
                                 -0.25f, 0.75f, 0.1f, 0.2f, 0.3f, 0.4f,
                                 0.5f, 0.6f, 0.7f, 0.8f};
    const size_t num_inputs = sizeof(test_inputs) / sizeof(test_inputs[0]);
    ASSERT_EQ(num_inputs, num_samples);

    for (size_t i = 0; i < num_inputs; ++i) {
        alignas(64) float cpp_out[MAX_D_MODEL];
        block->process_sample(test_inputs[i], cpp_out);

        const float* py_out = expected.data() + i * d_model;

        for (size_t j = 0; j < d_model; ++j) {
            // Check no NaN/Inf
            ASSERT_FALSE(std::isnan(cpp_out[j]))
                << "C++ NaN at sample " << i << " channel " << j;
            ASSERT_FALSE(std::isinf(cpp_out[j]))
                << "C++ Inf at sample " << i << " channel " << j;

            EXPECT_NEAR(cpp_out[j], py_out[j], 1e-5f)
                << "Mismatch at sample " << i << " channel " << j
                << " C++=" << cpp_out[j] << " Python=" << py_out[j];
        }
    }
}
